                    <button onClick="{{ abrirMetaNueva }}" style="flex:none;display:flex;align-items:center;gap:6px;padding:8px 14px;border-radius:13px;border:1px solid {{ tema.borde }};background:{{ tema.card }};color:{{ tema.tinta }};font-family:inherit;font-size:calc(13px * var(--letra, 1));font-weight:700;cursor:pointer"><svg viewBox="0 0 24 24" style="width:15px;height:15px" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round"><path d="M12 5v14M5 12h14"></path></svg>{{ rotuloNuevaMeta }}</button>
